from decimal import Decimal

def parse_number(text: str) -> Decimal:
    if not isinstance(text, str):
        raise ValueError("invalid input")
    s = text.strip(" \t\u00a0")
    if s == "":
        raise ValueError("empty input")
    negative = False
    # parentheses handling
    if "(" in s or ")" in s:
        if not (len(s) >= 2 and s[0] == "(" and s[-1] == ")"):
            raise ValueError("unbalanced parentheses")
        inner = s[1:-1]
        if inner == "":
            raise ValueError("empty parentheses")
        if "(" in inner or ")" in inner:
            raise ValueError("unbalanced parentheses")
        if "+" in inner or "-" in inner:
            raise ValueError("sign with parentheses")
        s = inner
        negative = True
    else:
        if s[0] == "+" or s[0] == "-":
            if s[0] == "-":
                negative = True
            s = s[1:]
            if s == "":
                raise ValueError("sign only")
            if s[0] == "+" or s[0] == "-":
                raise ValueError("double sign")
    # remove interior spaces (space and NBSP) as thousands separators
    s = s.replace(" ", "").replace("\u00a0", "")
    if s == "":
        raise ValueError("empty number")
    for ch in s:
        if not (("0" <= ch <= "9") or ch == "." or ch == ","):
            raise ValueError("invalid character")
    has_digit = False
    for ch in s:
        if "0" <= ch <= "9":
            has_digit = True
            break
    if not has_digit:
        raise ValueError("no digits")
    core = s
    has_dot = "." in core
    has_comma = "," in core
    decimal_sep = None
    thousands_sep = None
    if has_dot and has_comma:
        if core.rfind(".") > core.rfind(","):
            decimal_sep = "."
            thousands_sep = ","
        else:
            decimal_sep = ","
            thousands_sep = "."
    elif has_comma:
        if core.count(",") > 1:
            thousands_sep = ","
            decimal_sep = None
        else:
            decimal_sep = ","
            thousands_sep = None
    elif has_dot:
        if core.count(".") > 1:
            thousands_sep = "."
            decimal_sep = None
        else:
            decimal_sep = "."
            thousands_sep = None
    else:
        decimal_sep = None
        thousands_sep = None
    def _all_digits(part):
        if part == "":
            return False
        for c in part:
            if not ("0" <= c <= "9"):
                return False
        return True
    def _check_grouping(int_raw, sep):
        parts = int_raw.split(sep)
        for p in parts:
            if not _all_digits(p):
                raise ValueError("bad grouping")
        if not (1 <= len(parts[0]) <= 3):
            raise ValueError("bad grouping")
        for p in parts[1:]:
            if len(p) != 3:
                raise ValueError("bad grouping")
    if decimal_sep is not None:
        if core.count(decimal_sep) != 1:
            raise ValueError("bad decimal separator")
        int_raw, frac_raw = core.split(decimal_sep)
        if int_raw == "" or frac_raw == "":
            raise ValueError("empty integer or decimal part")
        if not _all_digits(frac_raw):
            raise ValueError("bad decimal part")
        if thousands_sep is None:
            if not _all_digits(int_raw):
                raise ValueError("bad integer part")
            int_digits = int_raw
        else:
            for c in int_raw:
                if not (("0" <= c <= "9") or c == thousands_sep):
                    raise ValueError("bad integer part")
            if thousands_sep in int_raw:
                _check_grouping(int_raw, thousands_sep)
                int_digits = int_raw.replace(thousands_sep, "")
            else:
                if not _all_digits(int_raw):
                    raise ValueError("bad integer part")
                int_digits = int_raw
        canon = int_digits + "." + frac_raw
    else:
        if thousands_sep is not None:
            int_raw = core
            if thousands_sep not in int_raw:
                raise ValueError("bad grouping")
            for c in int_raw:
                if not (("0" <= c <= "9") or c == thousands_sep):
                    raise ValueError("bad integer part")
            _check_grouping(int_raw, thousands_sep)
            int_digits = int_raw.replace(thousands_sep, "")
            canon = int_digits
        else:
            if not _all_digits(core):
                raise ValueError("bad integer")
            canon = core
    if canon == "":
        raise ValueError("empty number")
    if negative:
        canon = "-" + canon
    return Decimal(canon)
